"""Ownership model for PEP 752 package namespaces."""

from packagenamespaces import (
    hyphen_depth,
    is_valid_namespace,
    namespace_matches,
    normalize_name,
)

DEFAULT_DEPTH_LIMIT = 3

__all__ = [
    "DEFAULT_DEPTH_LIMIT",
    "Grant",
    "GrantError",
    "InvalidNamespaceError",
    "OverlapError",
    "DepthLimitError",
    "UnknownGrantError",
    "grants_overlap",
    "GrantStore",
]


class GrantError(Exception):
    """Base error for namespace grants."""


class InvalidNamespaceError(GrantError):
    """Raised when a namespace name is invalid."""


class OverlapError(GrantError):
    """Raised when a grant overlaps another owner's grant."""


class DepthLimitError(GrantError):
    """Raised when a namespace exceeds the depth limit."""


class UnknownGrantError(GrantError):
    """Raised when a namespace holds no grant."""


class Grant:
    """A single namespace grant."""

    def __init__(self, name, owner):
        self._name = normalize_name(name)
        self._owner = owner

    @property
    def name(self):
        return self._name

    @property
    def owner(self):
        return self._owner

    def __eq__(self, other):
        if not isinstance(other, Grant):
            return NotImplemented
        return self._name == other._name and self._owner == other._owner

    def __lt__(self, other):
        if not isinstance(other, Grant):
            return NotImplemented
        return (self._name, self._owner) < (other._name, other._owner)

    def __hash__(self):
        return hash((self._name, self._owner))

    def __repr__(self):
        return f"Grant(name={self._name!r}, owner={self._owner!r})"


def grants_overlap(first, second):
    """Return True when two namespaces overlap.

    Overlap appends a hyphen to both normalized names and is
    detected in both directions, so a longer namespace under an
    existing grant overlaps while foo and foobar do not overlap.
    """
    first_normalized = normalize_name(first)
    second_normalized = normalize_name(second)
    if first_normalized == second_normalized:
        return True
    return first_normalized.startswith(second_normalized + "-") or (
        second_normalized.startswith(first_normalized + "-")
    )


class GrantStore:
    """Store of active namespace grants."""

    def __init__(self, depth_limit=DEFAULT_DEPTH_LIMIT):
        self.depth_limit = depth_limit
        self._grants = {}

    def reserve(self, namespace, owner):
        """Reserve *namespace* for *owner*."""
        if not isinstance(owner, str) or owner == "":
            raise ValueError("owner must be a non-empty string")
        normalized = normalize_name(namespace)
        if not is_valid_namespace(normalized):
            raise InvalidNamespaceError(f"invalid namespace: {namespace!r}")
        if self.depth_limit is not None:
            if hyphen_depth(normalized) > self.depth_limit:
                raise DepthLimitError(
                    f"namespace {normalized!r} exceeds depth limit "
                    f"{self.depth_limit}"
                )
        for existing_name, existing_owner in self._grants.items():
            if grants_overlap(normalized, existing_name):
                if existing_owner != owner:
                    raise OverlapError(
                        f"namespace {normalized!r} overlaps the grant "
                        f"{existing_name!r}"
                    )
        self._grants[normalized] = owner
        return Grant(normalized, owner)

    def transfer(self, namespace, new_owner):
        """Transfer *namespace* to *new_owner*."""
        if not isinstance(new_owner, str) or new_owner == "":
            raise ValueError("owner must be a non-empty string")
        normalized = normalize_name(namespace)
        if normalized not in self._grants:
            raise UnknownGrantError(f"unknown grant {normalized!r}")
        for existing_name, existing_owner in self._grants.items():
            if existing_name == normalized:
                continue
            if grants_overlap(normalized, existing_name):
                if existing_owner != new_owner:
                    raise OverlapError(
                        f"namespace {normalized!r} overlaps the grant "
                        f"{existing_name!r}"
                    )
        self._grants[normalized] = new_owner
        return Grant(normalized, new_owner)

    def remove(self, namespace):
        """Remove the grant for *namespace*."""
        normalized = normalize_name(namespace)
        if normalized not in self._grants:
            raise UnknownGrantError(f"unknown grant {normalized!r}")
        del self._grants[normalized]

    def get(self, namespace):
        """Return the grant for *namespace* or None when ungranted."""
        if not isinstance(namespace, str):
            return None
        try:
            normalized = normalize_name(namespace)
        except TypeError:
            return None
        owner = self._grants.get(normalized)
        if owner is None:
            return None
        return Grant(normalized, owner)

    def namespaces(self):
        """Return sorted granted namespace names."""
        return sorted(self._grants.keys())

    def matching(self, project):
        """Return sorted grants matching *project*."""
        if not isinstance(project, str):
            return []
        normalized = normalize_name(project)
        result = []
        for name, owner in self._grants.items():
            if namespace_matches(name, normalized):
                result.append(Grant(name, owner))
        result.sort(key=lambda grant: grant.name)
        return result

    def parent(self, namespace):
        """Return the granted parent name or None without a grant."""
        if not isinstance(namespace, str):
            return None
        try:
            normalized = normalize_name(namespace)
        except TypeError:
            return None
        if normalized not in self._grants:
            return None
        if "-" not in normalized:
            return None
        immediate = normalized.rsplit("-", 1)[0]
        if immediate in self._grants:
            return immediate
        return None

    def children(self, namespace):
        """Return sorted granted direct child names."""
        if not isinstance(namespace, str):
            return []
        try:
            normalized = normalize_name(namespace)
        except TypeError:
            return []
        if normalized not in self._grants:
            return []
        prefix = normalized + "-"
        result = []
        for name in self._grants:
            if not name.startswith(prefix):
                continue
            immediate = name.rsplit("-", 1)[0] if "-" in name else None
            if immediate == normalized:
                result.append(name)
        return sorted(result)

    def __len__(self):
        return len(self._grants)

    def __contains__(self, item):
        if not isinstance(item, str):
            return False
        try:
            normalized = normalize_name(item)
        except TypeError:
            return False
        return normalized in self._grants
